class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.zeros(dim)

    def _evaluate(self, x, func):
        if self.evals >= self.budget: return float('inf')
        f = func(x)
        self.evals += 1
        if f < self.best_f:
            self.best_f = f
            self.best_x = x.copy()
        return f

    def _cmaes_continuous(self, n_iter=100):
        # Initialize with LHS
        pop = lhs(n_samples=10, n_dim=18)
        cma_opt = CMAEvolutionStrategy(pop, 0.25, inopts={'popsize': 10})
        for _ in range(n_iter):
            cma_opt.optimize(self._evaluate, x0=[], grad=None)

    def _ga_categorical(self, n_iter=100):
        # Initialize with LHS and round to nearest integer for categorical variables (x[18:24])
        pop = lhs(n_samples=10, n_dim=6)
        for i in range(18, self.dim):
            pop[:, i] = np.round(pop[:, i])
        for x in pop: self._evaluate(x, self.func)

        # Crossover and mutation
        parents = pop[np.argsort(self.best_f - pop[:, 0])[:5]]
        children = np.zeros((10, self.dim))
        for i in range(10):
            child = parents[i].copy()
            parent1 = parents[np.random.choice(range(5))]
            parent2 = parents[np.random.choice(range(5))]
            for j in range(18, self.dim):
                child[j] = (parent1[j] + parent2[j]) / 2
            children[i] = child
        pop = np.concatenate((pop, children))
        self._ga_mutation(pop)

    def _ga_mutation(self, pop):
        # Mutation for categorical variables (x[18:24])
        for i in range(18, self.dim):
            for j, x in enumerate(pop):
                r = np.random.uniform()
                if r < 0.5 and pop[np.random.choice(len(pop))][i] != x[i]:
                    pop[j][i] = pop[np.random.choice(len(pop))][i]

    def __call__(self, func, grad_func=None):
        self._cmaes_continuous()
        self._ga_categorical()
        return self.best_f, self.best_x

