class IterativeRefinementOptimizer(Optimizer):
    def __init__(self, budget: int, dim: int):
        super().__init__(budget, dim)
        self.n_lbfgs = 50

    def _continuous_optimization(self, x0=None):
        if x0 is None:
            samples = lhs(n_samples=1, n_dim=18)
            x0 = samples[0]
        res = minimize(self._evaluate, x0, method='L-BFGS-B', bounds=[(-1, 1)]*len(x0), options={'maxiter': self.n_lbfgs})
        return res.x

    def _discrete_optimization(self):
        # Initialize with LHS and round to nearest integer for categorical variables (x[18:24])
        samples = lhs(n_samples=self.budget-self.n_lbfgs, n_dim=6)
        for i in range(18, self.dim):
            samples[:, i] = np.round(samples[:, i])
        best_fitnesses = np.zeros(self.budget - self.n_lbfgs)
        best_x = None
        for i, sample in enumerate(samples):
            f = self._evaluate(sample, self.func)
            best_fitnesses[i] = f
            if f < np.min(best_fitnesses):
                best_fitnesses[:i] = float('inf')
                best_x = sample
        return best_x

    def __call__(self, func, grad_func=None):
        x0 = self._continuous_optimization()
        x = self._discrete_optimization() if self.evals >= self.n_lbfgs else x0
        return self._evaluate(x, func)

