    def __init__(self, budget: int, dim: int):
        super().__init__(budget, dim)
        self.best_x = None  # Store the best found point to perform gradient-biased exploration

    def _evaluate(self, x, func):
        if self.evals >= self.budget or self.best_x is None: return float('inf')

        f = self._evaluate(self.best_x, func)  # Re-evaluate the best found point for a new score
        if x is not None and x != self.best_x:
            grad = np.array([grad_func(y)[i] for i, y in enumerate(zip(self.best_x, x))])  # Compute the gradient of the improvement between the best found point and the current candidate
            step = -0.1 * grad / np.linalg.norm(grad)  # Take a small step towards the direction of improvement
            new_x = self.best_x + step  # Perform gradient-biased exploration
            f = self._evaluate(new_x, func)  # Evaluate the improved point and store it as the best found point if better
            self.best_x = new_x.copy() if f < f else self.best_x  # Update the best found point only if the improvement is positive

        return f

    def __call__(self, func, grad_func=None):
        if grad_func is None: raise ValueError("grad_func must be provided to GradientBiasedExplorer")
