class DEHybridOptimizer(Optimizer):
    def __init__(self, budget: int, dim: int):
        super().__init__(budget, dim)
        self.f = None  # Current best fitness value
        self.x = None  # Current best solution
        self.population = []  # Current population
        self.F = None  # F parameter for DE mutation
        self.CR = None  # Crossover rate

    def _initialize_population(self):
        self.population = lhs(n_samples=self.budget, n_dim=self.dim)
        self._find_best()

    def _find_best(self):
        self.f = float('inf')
        for x in self.population:
            if self._evaluate(x) < self.f:
                self.f, self.x = self._evaluate(x), x

    def _generate_trial(self, x):
        # DE mutation for continuous variables (x[0:18]) and uniform crossover for categorical variables (x[18:24])
        x_copy = np.copy(x)
        for i in range(18, 24):
            if isinstance(x[i], int):
                # Uniform crossover for discrete variables
                rand_idx = np.random.randint(0, self.budget, size=1)[0]
                x_copy[i] = self.population[rand_idx][i]
            else:
                # DE mutation for continuous variables
                r1, r2 = self._select_individuals(i)
                F = np.random.uniform(self.F[0], self.F[1])
                x_copy[i] = x[i] + F * (r2[i] - r1[i])
        return x_copy

    def _select_individuals(self, idx):
        r1, r2 = np.random.randint(0, self.budget, size=2)
        while r1 == r2:
            r2 = np.random.randint(0, self.budget)
        return self.population[r1], self.population[r2]

    def _evaluate(self, x):
        if self.evals >= self.budget: return float('inf'), None
        fitness = self._evaluate_and_update(x)
        if fitness < self.f:
            self.f, self.x = fitness, x
        return fitness, x

    def _evaluate_and_update(self, x):
        fitness = self._evaluate(x)
        if isinstance(x[18], int):  # If the sample has categorical values
            self._update_best_materials(x)
        return fitness

    def _update_best_materials(self, x):
        material_idx = int(x[18])
        if self.population[material_idx].f < self.x.f:
            self.x = np.copy(self.population[material_idx])

    def __call__(self, func, grad_func=None):
        self._initialize_population()  # Initialize population with LHS samples
        for i in range(self.budget - 1):
            trial = self._generate_trial(self.population[i])
            fitness, _ = self._evaluate(trial)
            if fitness < self.population[i].f:
                self.population[i] = np.copy(trial)
        return self.x.f, self.x

