class DEOptimizer(HybridOptimizer):
    def __init__(self, budget: int, dim: int):
        super().__init__(budget, dim)
        self.F = 0.5  # Differential weight factor
        self.CR = 0.8  # Crossover rate

    def _mutate(self, x, idx_continuous: list):
        NP = np.copy(x)  # Target vector to store the mutated solution

        for i in idx_continuous:
            # DE Mutation (F parameter)
            a = self._get_differential(x[i], x[(i + self.dim - 1) % self.dim], x[(i + self.dim - 2) % self.dim])
            b = self._get_differential((x[i] + x[(i + 1) % self.dim]) / 2, (x[(i + 1) % self.dim] + x[(i + 2) % self.dim]) / 2, x[(i + 2) % self.dim])
            NP[i] = x[i] + self.F * (b - a)

        return NP

    def _get_differential(self, x1, x2, x3):
        return x2 - x1 + self.CR * (x3 - x1)

    def _crossover(self, parent, offspring, idx_discrete: list):
        for i in idx_discrete:
            # Uniform Crossover for discrete variables
            if np.random.uniform() < self.CR:
                offspring[i] = parent[i]

    def _evaluate(self, x, func):
        if self.cma_es is None:
            # Initialize CMA-ES for continuous variables (x[0:18])
            self.cma_es = cma.CMAEvolutionStrategy(np.zeros(18), np.ones(18), inopts={'popsize': 50})

        if self.evals >= self.budget: return float('inf')

        idx_continuous = list(range(18))
        idx_discrete = list(range(24))
        idx_discrete[0:18] = []  # Remove continuous variables from discrete indices

        # Mutate the parent solution with DE mutation for continuous variables and uniform crossover for categorical variables
        offspring = self._mutate(x, idx_continuous)
        self._crossover(x, offspring, idx_discrete)

        full_x = np.concatenate([self.cma_es.ask(), offspring])
        f = self._evaluate_and_update(full_x, func)
        return f

