class IterativeOptimizer(Optimizer):
    def __init__(self, budget: int, dim: int):
        super().__init__(budget, dim)
        self.continuous_iters = 50
        self.discrete_iters = 100

    def _optimize_continuous(self, x):
        # Optimize continuous variables with L-BFGS-B for specified iterations
        res = minimize(self._evaluate, x, method='L-BFGS-B', bounds=[(-1, 1)]*len(x), options={'maxiter': self.continuous_iters})
        if res.success:
            return res.x
        else:
            # If L-BFGS-B fails, return the initial input (x)
            return x

    def _optimize_discrete(self, x):
        # Perform discrete coordinate search on categorical variables (x[18:24])
        for i in range(18, self.dim):
            best = np.copy(x)
            for j in range(6):
                new_x = np.copy(best)
                new_x[i] += j
                f = self._evaluate(new_x, self.func)
                if f < self._evaluate(best, self.func):
                    best = new_x
            x[i] = best[i]
        return x

    def __call__(self, func, grad_func=None):
        # Optimize continuous variables using L-BFGS-B and discrete coordinate search on categorical glass IDs iteratively
        for _ in range(self.budget // (self.continuous_iters + self.discrete_iters) + 1):
            x = lhs(n_samples=1, n_dim=self.dim)
            x = self._optimize_continuous(x)
            self._optimize_discrete(x)
        return self.best_f, self.best_x

