class HybridOptimizer(Optimizer):
    def __init__(self, budget: int, dim: int):
        super().__init__(budget, dim)

    def _initial_population(self):
        # Use LHS for initial sampling
        pop = lhs(n_samples=10, n_dim=24)
        # Round to nearest integer for categorical variables (x[18:24])
        for i in range(18, self.dim):
            pop[:, i] = np.round(pop[:, i])
        return pop

    def _hybrid_strategy(self, n_iter=100):
        # Initialize population with LHS
        pop = self._initial_population()
        cma_opt = CMAEvolutionStrategy(pop[:, :18], 0.25, inopts={'popsize': 10})

        for _ in range(n_iter):
            # Run CMA-ES on continuous variables while keeping categorical variables fixed
            f_list = []
            for x in pop: self._evaluate(x, self.func)
            best_f, best_x = cma_opt.optimize(self._evaluate, x0=[best_x], grad=None).x[0]

            # Periodical mutation for categorical variables
            if (_ + 1) % (n_iter // 20) == 0:
                self._periodic_mutation(pop)

    def _periodic_mutation(self, pop):
        # Mutate the glass IDs using random swaps for the best individuals
        best_ind = np.argsort(best_x[:, 18:24])[::-1][:5]
        pop[best_ind] = np.random.permutation(pop[best_ind])

    def __call__(self, func, grad_func=None):
        self._hybrid_strategy()
        return self.best_f, self.best_x
